// failover controller — runs on the standby
let lastBeat = Date.now();

onHeartbeat(() => { lastBeat = Date.now(); });

setInterval(() => {
  const silentMs = Date.now() - lastBeat;
  if (silentMs > 1000) {                // 1s without a beat => primary dead
    promoteSelf();                       // become the new primary
    startAcceptingWrites();              // immediately take writes
  }
}, 500);
